\begin{align*}
    {w}_1 &= {v}_1& {q}_1 = {w}_1/{\left\lVert{w}_1\right\rVert}\\
    {w}_2 &= {v}_2 - {\left\langle{q}_1,{v}_2\right\rangle} {q}_1 & {q}_2 = {w}_2 / {\left\lVert{w}_2\right\rVert}\\
    &\ldots\\
    {w}_k &= {v}_k - \sum_{j=1}^{k-1}{\left\langle{q}_j,{v}_k\right\rangle} {q}_j & {q}_k = {w}_k / {\left\lVert{w}_k\right\rVert}\\
    &\ldots
\end{align*}


