  \left[J(u(x),v(x))\right]_a^b &= \boldsymbol{y}^{\mathsf{H}}{\mathsf{P}}\boldsymbol{x} \\ &=\begin{bmatrix}v(a)\\v'(a)\\v(b)\\v'(b)\end{bmatrix}^{\mathsf{H}}\begin{bmatrix} 0 & +p(a) & 0 & 0 \\ -p(a) & 0 & 0 & 0 \\ 0 & 0 & 0 & -p(b) \\ 0 & 0 & +p(b) & 0\end{bmatrix} \begin{bmatrix}u(a)\\u'(a)\\u(b)\\u'(b)\end{bmatrix}\\
  &= p(b) \det\left(\begin{bmatrix}
    u(b) & \overline{v(b)} \\ u'(b) & \overline{v'(b)}
  \end{bmatrix}\right) - p(a) \det\left(\begin{bmatrix}
    u(a) & \overline{v(a)} \\ u'(a) & \overline{v'(a)}
  \end{bmatrix}\right).
\end{align*}


